#[path="stem_parts_lookup.rs"]mod lookup;
use audiveris_native::{beam_dispatch,vertical_sticks::SeedSection};
use serde_json::{Value,json};
fn main(){let args=std::env::args().collect::<Vec<_>>();let f:Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let sections=|name:&str|f[name].as_array().unwrap().iter().map(|s|{let x:SeedSection=serde_json::from_value(s.clone()).unwrap();assert_eq!(serde_json::to_value(lookup::center(&x)).unwrap(),s["centroid"]);x}).collect::<Vec<_>>();let v=sections("vertical_sections");let h=sections("horizontal_sections");let mut rows=Vec::new();for(index,c)in f["cases"].as_array().unwrap().iter().enumerate(){let mut points=Vec::new();for segment in c["area_path"].as_array().unwrap(){match segment["type"].as_i64().unwrap(){0|1=>points.push(serde_json::from_value(segment["coordinates"].clone()).unwrap()),4=>{},_=>panic!("nonlinear path")}}
 let stump=(!c["stump"].is_null()).then(||beam_dispatch::glyph_from_json(&c["stump"]).unwrap());let p=lookup::Parameters{direction:c["direction"].as_i64().unwrap() as i8,slope:c["slope"].as_f64().unwrap(),max_stem_thickness:c["max_stem_thickness"].as_i64().unwrap(),max_line_section_dx:c["max_line_section_dx"].as_f64().unwrap(),last_head_y:c["last_head_y"].as_f64(),theoretical_line:serde_json::from_value(c["theoretical_line"].clone()).unwrap()};let n=lookup::collect(&v,&h,&points,stump.as_ref(),&p).unwrap_or_else(|e|panic!("case{index}: {e}"));assert_eq!(json!(n.vertical_ids),c["selected_vertical_ids"],"case{index} vertical");assert_eq!(json!(n.horizontal_ids),c["selected_horizontal_ids"],"case{index} horizontal");assert_eq!(json!(n.raw_glyphs),c["raw_sticks_min_core0"],"case{index} glyphs");rows.push(json!({"selected_vertical_ids":n.vertical_ids,"selected_horizontal_ids":n.horizontal_ids,"raw_sticks":n.raw_glyphs}));}std::fs::write(&args[2],serde_json::to_vec_pretty(&json!({"scope":"Work-only native Rust automatic section lookup/raw assembly; single original trial, observed areas supplied, not independently certified","cases":rows})).unwrap()).unwrap();println!("Matched all {} selected section sets and raw physical glyphs",rows.len());}
